#!/usr/bin/env python3
"""Create a self-contained, searchable local index of the reference."""
import json
from html import escape
from pathlib import Path
from archive_site import ROOT, DATA, write

def main():
    load=lambda n:json.loads((DATA/n).read_text())
    summary=load('summary.json'); pages=load('page-catalog.json'); tokens=load('tokens.reference.json')['records']; classes=load('class-catalog.json'); buttons=load('button-variants.json')
    page_cards=''.join('<a class="card" href="archive/site/'+p['path']+'"><span>'+escape(p['url'].replace('https://variable-design-system.webflow.io','') or '/')+'</span><strong>'+escape(p['title'])+'</strong><small>Открыть локальную копию ↗</small></a>' for p in pages)
    payload=json.dumps({'tokens':tokens,'classes':classes,'buttons':buttons},ensure_ascii=False).replace('</','<\\/')
    template='''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Design reference / Variable System</title><style>
:root{--ink:#151719;--paper:#f5f5ef;--line:#d9dcd4;--muted:#565e59;--accent:#d9f37f}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 system-ui,sans-serif}main{max-width:1320px;padding:36px 40px 80px;margin:auto}a{color:inherit}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:18px;font-size:13px}.brand{font-weight:750;letter-spacing:.07em}header span{color:var(--muted)}.hero{display:grid;grid-template-columns:1.6fr 1fr;gap:70px;align-items:end;padding:65px 0 44px}h1{font-size:clamp(38px,5.5vw,72px);letter-spacing:-.06em;line-height:1.05;margin:12px 0 22px}h2{font-size:26px;letter-spacing:-.025em}h3{font-size:18px}p{max-width:70ch}.eyebrow{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}.intro{color:var(--muted);margin:0}.tag{display:inline-block;padding:5px 9px;background:var(--accent);font-size:12px;font-weight:700}.stats{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--line);margin:16px 0 48px}.stat{padding:22px;border-right:1px solid var(--line)}.stat:last-child{border:0}.stat b{display:block;font-size:36px;letter-spacing:-.05em}.stat span{font-size:13px;color:var(--muted)}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card{display:flex;flex-direction:column;gap:18px;padding:22px;border:1px solid var(--line);background:#fff;text-decoration:none;min-height:200px;transition:transform .15s}.card:hover{transform:translateY(-3px);border-color:#747e6d}.card>span{font:12px/1.5 ui-monospace,monospace;color:var(--muted);overflow-wrap:anywhere}.card strong{font-size:20px;line-height:1.2}.card small{margin-top:auto;color:var(--muted)}section{margin:48px 0}.note{background:#e8ecdf;border-left:3px solid #96ac6e;padding:18px 22px;font-size:14px}.links{display:flex;flex-wrap:wrap;gap:12px}.links a{border:1px solid var(--ink);padding:10px 16px;text-decoration:none}.links a:first-child{background:var(--ink);color:white}.controls{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}input,select{font:inherit;color:inherit;border:1px solid #9ba296;border-radius:3px;background:#fff;padding:12px}input{flex:1;min-width:200px}select{min-width:170px}.results{border:1px solid var(--line);background:#fff;max-height:680px;overflow:auto}.row{display:grid;grid-template-columns:1.15fr 1fr .8fr;gap:18px;padding:15px 20px;border-bottom:1px solid var(--line);font-size:14px}.row:last-child{border:0}.row code{overflow-wrap:anywhere;font-size:12px}.row small{color:var(--muted);overflow-wrap:anywhere}.count{font-size:13px;color:var(--muted)}.split{display:grid;grid-template-columns:1fr 1fr;gap:36px}.split article{border-top:1px solid var(--line)}footer{border-top:1px solid var(--line);padding-top:24px;font-size:12px;color:var(--muted)}:focus-visible{outline:3px solid #7a9740;outline-offset:4px}@media(max-width:800px){main{padding:24px 20px}.hero,.split{grid-template-columns:1fr;gap:20px}.hero{padding-top:40px}.cards,.stats{grid-template-columns:repeat(2,1fr)}.row{grid-template-columns:1fr}.stats .stat:nth-child(2){border-right:0}}@media(max-width:450px){header{align-items:start;gap:20px}.cards{grid-template-columns:1fr}.stat{padding:15px}.stat b{font-size:30px}.links a{width:100%}}@media(prefers-reduced-motion:reduce){.card{transition:none}}
</style></head><body><main><header><div class="brand">DESIGN / REFERENCE LIBRARY</div><span>Snapshot 25.09.2026</span></header>
<div class="hero"><div><span class="tag">VARIABLE DESIGN SYSTEM</span><h1>Система за<br>визуальным слоем.</h1><p class="intro">Токены, компоненты и правила построения интерфейса. Оригинал Caleb Raney, каталог и независимая адаптация.</p></div><p>Материал для последовательной верстки и общей базы знаний. Визуальная концепция и состав секций задаются требованиями конкретного проекта.</p></div>
<div class="stats"><div class="stat"><b>4</b><span>публичные страницы</span></div><div class="stat"><b>108</b><span>CSS-переменных</span></div><div class="stat"><b>22</b><span>сочетания кнопок</span></div><div class="stat"><b>48 / 49</b><span>ресурсов скачано</span></div></div>
<section><div class="eyebrow">01 / Original reference</div><h2>Все обнаруженные страницы</h2><div class="cards">__CARDS__</div></section>
<section class="split"><article><div class="eyebrow">02 / What transfers</div><h2>Подходит для CSS и React</h2><p>Семантические цвета, шкала отступов, адаптивная типографика и организация компонентов не требуют Webflow.</p><div class="links"><a href="portable/example.html">Открыть независимый пример ↗</a><a href="docs/01-analysis.md">Читать анализ</a></div></article><article><div class="eyebrow">03 / Source review</div><h2>Есть ошибки в исходнике</h2><p>Найдены циклы H6, некорректные мобильные media queries и checkbox в примере Radio. Исправления вынесены в portable/.</p><a href="docs/04-source-issues.md">Открыть разбор ошибок ↗</a></article></section>
<section><div class="eyebrow">04 / Searchable inventory</div><h2>Найти правило или токен</h2><div class="controls"><input id="query" aria-label="Поиск по каталогу" placeholder="Например: spacing, heading, button…"><select id="kind" aria-label="Раздел каталога"><option value="tokens">Переменные</option><option value="classes">CSS-классы</option><option value="buttons">Кнопки</option></select></div><p id="count" class="count" aria-live="polite"></p><div id="results" class="results"></div></section>
<aside class="note">Сохранена опубликованная версия. Один стандартный SVG вернул HTTP 403. Внешние видео и документация остаются ссылками. Это не экспорт исходного проекта Webflow. <a href="README.md">Объем и ограничения</a>.</aside>
<footer>Источники: Caleb Raney · Client-First / Finsweet · Relume · Webflow. <a href="THIRD_PARTY_NOTICES.md">Происхождение</a> · <a href="data/archive-manifest.json">Manifest</a> · <a href="evidence/verification.json">Проверка</a></footer></main>
<script type="application/json" id="inventory">__PAYLOAD__</script><script>
const data=JSON.parse(document.getElementById('inventory').textContent),query=document.getElementById('query'),kind=document.getElementById('kind'),results=document.getElementById('results');
function node(tag,text){const n=document.createElement(tag);n.textContent=text;return n;}
function render(){const q=query.value.trim().toLowerCase(),k=kind.value,rows=data[k].filter(r=>JSON.stringify(r).toLowerCase().includes(q));document.getElementById('count').textContent=rows.length+' записей';results.replaceChildren();for(const r of rows){const row=node('div','');row.className='row';if(k==='tokens'){row.append(node('code',r.name),node('code',r.value),node('small',(r.context.join(' · ')||'Base')+' · '+r.source));}else if(k==='classes'){row.append(node('code','.'+r.name),node('span',r.category),node('small',r.rules.length+' CSS rules · '+r.used_on.length+' pages'));}else{row.append(node('code',r.classes),node('span',r.text||'Icon-only'),node('small',r.tag));}results.append(row);}if(!rows.length)results.append(node('p','Совпадений нет. Попробуйте другое имя.'));}
query.addEventListener('input',render);kind.addEventListener('change',render);render();
</script></body></html>'''
    write(ROOT/'index.html',template.replace('__CARDS__',page_cards).replace('__PAYLOAD__',payload))
    md='# Карта публичного сайта\n\nОбнаружено четыре страницы через sitemap и рекурсивные внутренние ссылки. Количество страниц не включает внешнюю документацию и якоря внутри страниц.\n\n'
    for p in pages:
        md+='## '+p['title']+'\n\n'+p['url']+'\n\nЛокальная копия: `archive/site/'+p['path']+'`.\n\n'
        if p['styleguide_sections']: md+='Основные группы: '+', '.join(p['styleguide_sections'])+'.\n\n'
        headings=[h['text'] for h in p['headings'] if h['level']<=4]
        if headings: md+='Заголовки: '+', '.join(headings)+'.\n\n'
    write(ROOT/'docs/02-page-map.md',md.rstrip()+'\n')
    print('Built index.html and docs/02-page-map.md')

if __name__=='__main__': main()
